n, x = map(int, input().split())
arr = list(map(int, input().split()))

# For each element, calculate its two possible values
# and track how many elements can reach each value
value_count = {}

for ai in arr:
    val1 = ai
    val2 = ai & x

    # Track how many elements can reach each value
    if val1 in value_count:
        value_count[val1] += 1
    else:
        value_count[val1] = 1

    if val2 in value_count:
        value_count[val2] += 1
    else:
        value_count[val2] = 1

# Now find the minimum operations
min_ops = float('inf')

for val, count in value_count.items():
    if count >= 2:
        # Find the minimum operations to make two elements equal to this value
        # We need to find two elements that can reach this value
        # and calculate the total operations

        # Find all elements that can reach this value
        elements = []
        for ai in arr:
            if ai == val or (ai & x) == val:
                elements.append(ai)

        # Try all pairs of elements
        for i in range(len(elements)):
            for j in range(i + 1, len(elements)):
                # Calculate operations for element i to reach val
                ops_i = 0 if elements[i] == val else 1
                # Calculate operations for element j to reach val
                ops_j = 0 if elements[j] == val else 1

                total_ops = ops_i + ops_j

                if total_ops < min_ops:
                    min_ops = total_ops

if min_ops != float('inf'):
    print(min_ops)
else:
    print(-1)
