import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    requests = list(map(int, data[2:2+n]))

    current_books = set()
    cost = 0

    for day, book in enumerate(requests, 1):
        if book in current_books:
            continue

        # Need to buy the book
        cost += 1

        # If library is full, need to replace
        if len(current_books) >= k:
            # Find the book to replace: the one not needed for the longest time
            farthest_future = -1
            book_to_remove = None

            for candidate in current_books:
                # Find next occurrence of candidate
                next_day = None
                for future_day in range(day, n + 1):
                    if requests[future_day - 1] == candidate:
                        next_day = future_day
                        break

                if next_day is None:
                    # Book not needed again, remove it
                    book_to_remove = candidate
                    farthest_future = n + 1  # Beyond last day
                    break
                else:
                    if next_day > farthest_future:
                        farthest_future = next_day
                        book_to_remove = candidate

            current_books.remove(book_to_remove)

        current_books.add(book)

    print(cost)

if __name__ == "__main__":
    solve()
"}

