import sys

def is_unique_topological_sort(n, edges):
    """Check if the given edges uniquely determine a topological sort"""
    # Build adjacency list and in-degree count
    adj = [[] for _ in range(n + 1)]
    in_degree = [0] * (n + 1)

    for u, v in edges:
        adj[u].append(v)
        in_degree[v] += 1

    # Check for cycles and uniqueness
    queue = []
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    # If more than one node with in-degree 0, not unique
    if len(queue) > 1:
        return False

    # Perform topological sort
    top_order = []
    while queue:
        u = queue.pop(0)
        top_order.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Check if all nodes were visited
    if len(top_order) != n:
        return False  # Cycle detected

    # Check if topological sort is unique
    # At every step, there should be exactly one node with in-degree 0
    # We can re-check this by rebuilding in-degree and checking

    # Rebuild in-degree and check uniqueness
    in_degree = [0] * (n + 1)
    for u, v in edges:
        in_degree[v] += 1

    queue = []
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    unique = True
    while queue:
        if len(queue) > 1:
            unique = False
            break
        u = queue.pop(0)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    return unique

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    edges = []
    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        edges.append((u, v))

    for k in range(1, m + 1):
        current_edges = edges[:k]
        if is_unique_topological_sort(n, current_edges):
            print(k)
            return

    print(-1)

if __name__ == "__main__":
    solve()
"}

