import sys

def restore_address(s):
    # Find the protocol
    if s.startswith("http"):
        protocol = "http"
        s = s[4:]  # Remove "http"
    elif s.startswith("ftp"):
        protocol = "ftp"
        s = s[3:]  # Remove "ftp"
    else:
        return ""

    # Find where .ru starts (this is the domain part)
    # We need to find "ru" in the remaining string
    # The domain ends with .ru, so we need to find "ru" such that everything after is context
    # But we also need to make sure there's something before .ru (the domain)

    # Try to find "ru" such that there's at least one character before it
    for i in range(len(s) - 1):
        if s[i] == "r" and s[i+1] == "u":
            # Check if there's something before "ru" (domain)
            if i > 0:
                # Domain is from start to i-1, .ru is at i and i+1, context is from i+2
                domain = s[:i]
                context = s[i+2:]
                return f"{protocol}://{domain}.ru/{context}"

    # If no context, just return up to "ru"
    for i in range(len(s) - 1):
        if s[i] == "r" and s[i+1] == "u":
            if i > 0:
                return f"{protocol}://{s[:i]}.ru"

    return ""

def main():
    s = sys.stdin.read().strip()
    print(restore_address(s))

if __name__ == "__main__":
    main()
"}

