    for _ in range(n):
        x = int(data[idx])
        y = int(data[idx + 1])
        idx += 2

        # Count points with same x-coordinate
        x_counts[x] = x_counts.get(x, 0) + 1

        # Count points with same y-coordinate
        y_counts[y] = y_counts.get(y, 0) + 1

        # Count points that are exactly the same
        if (x, y) in points:
            same_point += 1
        else:
            points[(x, y)] = 1

    # Calculate number of pairs
    # C(count, 2) = count * (count - 1) // 2
    total = 0

    for count in x_counts.values():
        total += count * (count - 1) // 2

    for count in y_counts.values():
        total += count * (count - 1) // 2

    # Subtract pairs that have both same x and same y
    total -= same_point * (same_point - 1) // 2

    print(total)

