def solve():
    s = input().strip()
    t = input().strip()

    n, m = len(s), len(t)

    # dp[i][j] = maximum occurrences using first i characters of s, with last j characters matching t's last j characters
    dp = [[-1] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 0  # base case: 0 characters processed, 0 characters matched from the end of t

    for i in range(n):
        for j in range(m + 1):
            if dp[i][j] == -1:
                continue

            # Try to extend by one character
            char = s[i]
            if char == '?':
                # Try all 26 letters
                for k in range(26):
                    next_char = chr(ord('a') + k)
                    if next_char == t[m - j - 1]:
                        # This character matches, so we extend the match
                        new_j = j + 1
                        if new_j == m:
                            # We've matched the whole string t
                            dp[i + 1][0] = max(dp[i + 1][0], dp[i][j] + 1)
                        else:
                            dp[i + 1][new_j] = max(dp[i + 1][new_j], dp[i][j])
            else:
                # Fixed character
                if char == t[m - j - 1]:
                    new_j = j + 1
                    if new_j == m:
                        dp[i + 1][0] = max(dp[i + 1][0], dp[i][j] + 1)
                    else:
                        dp[i + 1][new_j] = max(dp[i + 1][new_j], dp[i][j])

    # The answer is the maximum occurrences we can achieve
    print(max(dp[n]))

