def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    k = int(next(it))

    universities = list(map(int, [next(it) for _ in range(2 * k)]))

    # Build tree
    tree = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        x, y = int(next(it)), int(next(it))
        tree[x].append(y)
        tree[y].append(x)

    # Calculate distance between all university pairs
    dist = []
    for i in range(len(universities)):
        dist_from_u = {universities[i]: 0}
        queue = [universities[i]]
        while queue:
            u = queue.pop(0)
            for v in tree[u]:
                if v not in dist_from_u:
                    dist_from_u[v] = dist_from_u[u] + 1
                    queue.append(v)
        dist.append(dist_from_u)

    # Find k pairs with maximum total distance
    result = 0
    used = [False] * (n + 1)

    # Create list of all university distances
    all_pairs = []
    for i in range(len(universities)):
        u1 = universities[i]
        for j in range(i + 1, len(universities)):
            if not used[universities[j]]:
                all_pairs.append((dist[i][universities[j]], universities[i], universities[j]))

    # Sort by distance descending
    all_pairs.sort(reverse=True, key=lambda x: x[0])

    # Select k pairs
