def count_billy_mistakes(N):
    """Count the number of triples (A, B, C) where AB ≠ C but (A * B) % 9 == C % 9"""
    # Count how many numbers in [1, N] are ≡ r (mod 9)
    count_remainder = [0] * 9
    for r in range(9):
        # Numbers ≡ r (mod 9) in [1, N]: r, r+9, r+18, ...
        # Count = floor((N - r) / 9) + 1 if r <= N else 0
        if r > N:
            count_remainder[r] = 0
        else:
            count_remainder[r] = (N - r) // 9 + 1

    count = 0
    for A in range(1, N + 1):
        for B in range(1, N + 1):
            # Compute (A * B) % 9
            r = (A * B) % 9
            # Count how many C's satisfy C % 9 == r and C ≠ A * B
            # Total C's with C % 9 == r: count_remainder[r]
            # Subtract 1 if A * B is in [1, N] and ≡ r (mod 9)
            if A * B <= N and (A * B) % 9 == r:
                count += count_remainder[r] - 1
            else:
                count += count_remainder[r]
