    triplets = []
    for x in range(1, n - 1):  # x from 1 to n-2
        for k in range(1, (n - x) // 2 + 1):
            if s[x-1] == s[x+k-1] == s[x+2*k-1]:
                triplets.append((x, x+2*k))  # store start and end

    # For each l, find the minimum end position among triplets that start >= l
    result = 0
    for l in range(1, n + 1):
        min_end = n + 1
        for t in triplets:
            if t[0] >= l and t[0] < t[1]:  # ensure x < x+2k
                min_end = min(min_end, t[1])
        if min_end <= n:
            result += n - min_end + 1

