def solve():
    MOD = 10**9 + 7
    s = input().strip()

    # dp[i] = number of valid sequences ending at or before position i
    dp = [0] * len(s)

    for i in range(len(s)):
        if s[i] == 'a':
            # We can start a new sequence at i
            # Or extend sequences that ended before i with a 'b' in between
            # dp[i] = dp[i-1] + 1
            if i == 0:
                dp[i] = 1
            else:
                dp[i] = dp[i-1] + 1
        else:
            # 'b', we can't start a sequence here
            if i == 0:
                dp[i] = 0
            else:
                dp[i] = dp[i-1]

    print(dp[-1] % MOD)

solve()
