import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    n = int(data[idx])
    idx += 1
    m = int(data[idx])
    idx += 1

    grid = []
    for i in range(n):
        row = data[idx]
        idx += 1
        grid.append(row)

    def is_center(i, j):
        # A cell is the center of a 3x3 square if it's not on the border
        return 0 < i < n-1 and 0 < j < m-1

    def is_on_border(i, j, x, y):
        # Check if (i, j) is on the border of the 3x3 square centered at (x, y)
        # It's on the border if it's in the square and not the center
        if not (x-1 <= i <= x+1 and y-1 <= j <= y+1):
            return False
        return not (i == x and j == y)

    # Check if it's impossible
    for i in range(n):
        for j in range(m):
            cell = grid[i][j]
            if cell == '#':
                # We need to find some center such that (i, j) is on its border
                found = False
                for x in range(n):
                    for y in range(m):
                        if is_on_border(i, j, x, y):
                            found = True
                            break
                    if found:
                        break
                if not found:
                    print("NO")
                    return
            else:
                # It must be the center of some 3x3 square
                if not is_center(i, j):
                    print("NO")
                    return

    print("YES")

if __name__ == "__main__":
    solve()
"}

