    if not data:
        return

    n = int(data[0])
    T = int(data[1])
    t = list(map(int, data[2:2+n]))

    time = 0
    count = 0

    for i in range(n):
        time += 1

        if time < T:
            if time >= t[i]:
                count += 1
            else:
                # We arrive early, decide whether to wait or skip
                # Wait if t[i] - time <= T - time - 1
                if t[i] - time <= T - time - 1:
