from collections import deque
import sys

def is_lucky(w):
    s = str(w)
    return all(c in '47' for c in s)

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    adj = [[] for _ in range(n)]
    for _ in range(n - 1):
        u = int(next(it))
        v = int(next(it))
        w = int(next(it))
        lucky = is_lucky(w)
        adj[u - 1].append((v - 1, lucky))
        adj[v - 1].append((u - 1, lucky))

    ans = 0

    for start in range(n):
        visited = [False] * n
        visited[start] = True
        queue = deque([(start, False)])
        count = 0

        while queue:
            v, has_lucky = queue.popleft()
            if v != start:
                count += 1

            for neighbor, is_lucky_edge in adj[v]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    new_has_lucky = has_lucky or is_lucky_edge
                    queue.append((neighbor, new_has_lucky))

        ans += count * (count - 1)

    print(ans)

if __name__ == "__main__":
    solve()
