import sys

def solve(n):
    """Count subarrays of length n with sum n*(n+1)//2"""
    if n <= 5:
        from itertools import permutations
        perms = list(permutations(range(1, n+1)))
        p = []
        for perm in perms:
            p.extend(perm)

        target_sum = n * (n + 1) // 2
        total = 0
        for i in range(len(p) - n + 1):
            sub = p[i:i+n]
            if sum(sub) == target_sum:
                total += 1

        return total

    # Use formula
    fact = 1
    for i in range(2, n+1):
        fact = fact * i % 998244353
    return (fact * (n - 1)) % 998244353

if __name__ == "__main__":
    n = int(sys.stdin.readline())
    print(solve(n))
