import sys

def count_ways(n):
    """Count the number of ways for a given n"""
    ways = 0
    k = 2
    while True:
        if k**3 > n:
            break
        ways += n // (k**3)
        k += 1
    return ways

def find_min_n(m):
    """Find the smallest n such that count_ways(n) = m"""
    # Binary search on n
    left = 1
    right = 2 * m  # Upper bound (we can refine this later)

    while left < right:
        mid = (left + right) // 2
        if count_ways(mid) < m:
            left = mid + 1
        else:
            right = mid

    # Check if the found n works
    if count_ways(left) == m:
        return left
    else:
        return -1

if __name__ == "__main__":
    m = int(sys.stdin.readline())
    result = find_min_n(m)
    print(result)
