def digital_root(x):
    """Calculate the digital root of x."""
    if x == 0:
        return 0
    return x % 9 if x % 9 != 0 else 9

def solve():
    N = int(input())

    # Count how many triples (A, B, C) satisfy d(A) * d(B) = d(C) but A * B != C
    count = 0

    for A in range(1, N + 1):
        for B in range(1, N + 1):
            for C in range(1, N + 1):
                dr_A = digital_root(A)
                dr_B = digital_root(B)
                dr_C = digital_root(C)

                # Check if digital root condition holds
                if dr_A * dr_B == dr_C:
                    # Check if actual multiplication doesn't match
                    if A * B != C:
                        count += 1

    print(count)

solve()
