import sys

def solve():
    c = sys.stdin.readline().strip()
    s = sys.stdin.readline().strip()
    t = sys.stdin.readline().strip()

    len_c = len(c)
    len_s = len(s)
    len_t = len(t)

    # DP: dp[i][ps][pt] = maximum value of f(c', s) - f(c', t)
    # where i is the current position in the string, ps is the number of characters of s matched so far,
    # pt is the number of characters of t matched so far, and the value is the difference between occurrences

    dp = [[[-float('inf')] * (len_t + 1) for _ in range(len_s + 1)] for _ in range(len_c + 1)]

    # Starting at position 0, matched 0 of s and 0 of t, value 0
    dp[0][0][0] = 0

    for i in range(len_c):
