    """Find the minimum number of discrete jumps from position 1 to position n."""

    # Use BFS to find minimum jumps
    from collections import deque

    # visited[i] = minimum jumps to reach position i (1-indexed)
    visited = [float('inf')] * (n + 1)
    visited[1] = 0

    # Queue for BFS
    queue = deque([1])

    while queue:
        current = queue.popleft()

        # Always can jump to next position
        if current + 1 <= n:
            if visited[current + 1] > visited[current] + 1:
                visited[current + 1] = visited[current] + 1
                queue.append(current + 1)

        # Find farthest position where all elements between are < min(h[current], h[farthest])
        # or > max(h[current], h[farthest])

        # Find the farthest position where all elements between are < min(h[current], h[farthest])
        farthest_less = current
        for j in range(current + 1, n + 1):
            if min(h[current - 1], h[j - 1]) > max(h[current], h[j]):
                farthest_less = j
            else:
                break

        # Find the farthest position where all elements between are > max(h[current], h[farthest])
        farthest_greater = current
        for j in range(current + 1, n + 1):
            if max(h[current - 1], h[j - 1]) < min(h[current], h[j]):
