def build_permutation(n):
    """Build a permutation that minimizes the sum of LIS and LDS lengths."""
    k = int(n ** 0.5) + 1  # number of blocks

    permutation = []
    for i in range(k):
        # Create a block with values from (i+1)*block_size to (i+2)*block_size
        block_size = n // k
        start = (i + 1) * block_size
        end = min((i + 2) * block_size, n + 1)
        block = list(range(start, end))
        permutation.extend(block)

    return permutation

def main():
