    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    q = int(next(it))

    for _ in range(q):
        n = int(next(it))
        t = [int(next(it)) for _ in range(n)]

        # Check if all types are the same
        all_same = all(t[0] == ti for ti in t)
        if all_same:
            print(1)
            print(' '.join(['1'] * n))
            continue

        # Find maximum chain of consecutive different types
        max_chain = 1
        current_chain = 1

        # Check wrap-around
        for i in range(n):
            if t[i] != t[(i + 1) % n]:
                current_chain += 1
                max_chain = max(max_chain, current_chain)
            else:
                current_chain = 1

        k = max_chain

        # Greedy coloring
        color = [1] * n
        for i in range(1, n):
            if t[i] != t[i - 1]:
                color[i] = color[i - 1] + 1
                if color[i] > k:
                    color[i] = 1

        print(k)
        print(' '.join(map(str, color)))

if __name__ == "__main__":
    solve()
