    s = sys.stdin.read().strip()
    n = len(s)

    # Find all triples (x, x+k, x+2k) where s[x] = s[x+k] = s[x+2k]
    triples = []
    for x in range(n):
        for k in range(1, n - x):
            if s[x] == s[x + k] == s[x + 2 * k]:
                triples.append((x + 1, x + k + 1, x + 2 * k + 1))  # 1-indexed

    # Count unique intervals [l, r] that contain at least one triple
    intervals = set()
    for a, b, c in triples:
        # Intervals that contain this triple: l <= a and r >= c
        for l in range(1, a + 1):
            for r in range(c, n + 1):
                intervals.add((l, r))

    print(len(intervals))

if __name__ == "__main__":
    solve()
