import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        m = int(next(it))

        # Read the matrix
        matrix = []
        for i in range(n):
            row = [int(next(it)) for _ in range(m)]
            matrix.append(row)

        # Group positions that must be equal
        groups = {}
        for i in range(n):
            for j in range(m):
                # Find the group representative (the smallest position in the group)
                rep = (i, j)
                if i > n - 1 - i:
                    rep = (n - 1 - i, j)
                if j > m - 1 - j:
                    rep = (rep[0], m - 1 - j)

                # Check if we need to mirror again (for the opposite corner)
                if rep[0] == n - 1 - rep[0] and rep[1] == m - 1 - rep[1]:
                    # This is the center of the matrix
                    rep = (rep[0], rep[1])
                else:
                    # Mirror again to get the opposite corner
                    rep = (n - 1 - rep[0], m - 1 - rep[1])

                # Add to the group
                if rep not in groups:
                    groups[rep] = []
                groups[rep].append(matrix[i][j])

        # Calculate operations
        total_ops = 0
        for vals in groups.values():
            # Find the median
            vals.sort()
            median = vals[len(vals) // 2]

            # Calculate operations to make all equal to median
            for val in vals:
                total_ops += abs(val - median)

        print(total_ops)

if __name__ == "__main__":
    solve()
