import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # dp[w] = maximum cost for total weight w
    dp = [0] * (m + 1)

    for _ in range(n):
        w = int(next(it))
        c = int(next(it))

        if w == 1:
            # For weight 1 items, we can just add them
            for weight in range(m, 0, -1):
                if dp[weight - 1] + c > dp[weight]:
                    dp[weight] = dp[weight - 1] + c
        elif w == 2:
            # For weight 2 items, we update in reverse order
            for weight in range(m, 1, -1):
                if dp[weight - 2] + c > dp[weight]:
                    dp[weight] = dp[weight - 2] + c
        elif w == 3:
            # For weight 3 items, we update in reverse order
            for weight in range(m, 2, -1):
                if dp[weight - 3] + c > dp[weight]:
                    dp[weight] = dp[weight - 3] + c

    print(dp[m])

