def is_lucky(w):
    """Check if a number is lucky (contains only digits 4 and 7)."""
    s = str(w)
    for ch in s:
        if ch not in ('4', '7'):
            return False
    return True

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))

    # Build adjacency list with only non-lucky edges
    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u = int(next(it))
        v = int(next(it))
        w = int(next(it))
        if not is_lucky(w):
            adj[u].append(v)
            adj[v].append(u)

    # Find connected components in the subgraph without lucky edges
    visited = [False] * (n + 1)
    component_sizes = [0] * (n + 1)

