import sys

def count_ways(n):
    """Count the number of ways thieves can steal chocolates for a given n."""
    ways = 0
    k = 2
    while True:
        k_cubed = k * k * k
        if k_cubed > n:
            break
        ways += n // k_cubed
        k += 1
    return ways

