    """Find the smallest n such that there are exactly m ways."""
    # Try values of n from 1 upwards
    n = 1
    while True:
        ways = count_ways(n)
        if ways == m:
            return n
        elif ways > m:
            # We've passed the target, return -1
            return -1
        n += 1

