    """Find the smallest n such that there are exactly m ways."""
    # Use binary search
    low = 1
    high = 1000000000000000  # A large upper bound

    while low < high:
        mid = (low + high) // 2
        ways = count_ways(mid)

        if ways < m:
            low = mid + 1
        else:
            high = mid

    # Verify
    ways = count_ways(low)
    if ways == m:
        return low
    else:
        return -1

