import sys

def can_jump(i, j, h):
    """Check if we can jump from i to j"""
    if i + 1 == j:
        return True

    # Get the maximum height between i and j
    max_between = max(h[i+1:j])

    # Check if all between are strictly lower than both
    if max_between < min(h[i], h[j]):
        return True

    # Check if all between are strictly higher than both
    if max_between > max(h[i], h[j]):
        return True

    return False

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    h = list(map(int, data[1:1+n]))

    current = 0  # 0-indexed, starting at first skyscraper
    jumps = 0

    while current < n - 1:
        # Find the farthest we can jump to
        farthest = current
        for next_pos in range(current + 1, n):
            if can_jump(current, next_pos, h):
                farthest = next_pos

        current = farthest
        jumps += 1

    print(jumps)

if __name__ == "__main__":
    solve()
