def is_isomorphic(subtree1, subtree2):
    """Check if two subtrees are isomorphic."""
    if subtree1 is None and subtree2 is None:
        return True
    if subtree1 is None or subtree2 is None:
        return False

    # Check if the current nodes have the same number of children
    if len(subtree1) != len(subtree2):
        return False

    # Check if the children of subtree1 can be matched to children of subtree2
    # by some permutation
    children1 = list(subtree1.values())
    children2 = list(subtree2.values())

    # Try all permutations of children2
    from itertools import permutations
    for perm in permutations(children2):
        match = True
        for c1, c2 in zip(children1, perm):
            if not is_isomorphic(c1, c2):
                match = False
                break
        if match:
            return True

    return False

def solve():
    n = int(input())
    a, b, c, d = map(int, input().split())
    parent = {}
    for i in range(2, n + 1):
        pi = int(input().split()[i - 2])
        parent[i] = pi

    # Build tree
    tree = {}
    for i in range(2, n + 1):
        p = parent[i]
        if p not in tree:
            tree[p] = {}
        tree[i] = {}  # No children for leaves

    # Build subtrees rooted at each node
    subtrees = {}
    for node in tree:
        subtrees[node] = tree[node].copy()

    # Find subtree containing a, b, c, d
    subtree_a = subtrees[parent[a]]
    subtree_b = subtrees[parent[b]]
    subtree_c = subtrees[parent[c]]
    subtree_d = subtrees[parent[d]]

    # Check isomorphism
    if is_isomorphic(subtree_a, subtree_b) and is_isomorphic(subtree_c, subtree_d):
        print("YES")
    else:
        print("NO")

