def count_paths(n, y):
    """Count how many numbers from 1 to n have y in their path."""

    # Numbers that eventually reach y through repeated applications of f
    # We can think of this as numbers that are on the 'tree' rooted at y

    # y itself
    if y <= n:
        count = 1
    else:
        return 0

    # y + 1 reaches y through f(y+1) = y
    if y + 1 <= n:
        count += 1

    # 2y reaches y through f(2y) = y
    if 2 * y <= n:
        count += 1

    return count

def solve(n, k):
    """Find the maximum y such that at least k numbers from 1 to n have y in their path."""

    # We need to find the maximum y such that count_paths(n, y) >= k

    # Iterate from n down to 1 and check count_paths(n, y) >= k
    for y in range(n, 0, -1):
        if count_paths(n, y) >= k:
            return y

    return 1

# Read input and output the result
