def has_unique_topological_sort(dag, n):
    """Check if a DAG has a unique topological sort"""
    # Copy the DAG to avoid modifying the original
    in_degree = [0] * (n + 1)
    for u in range(1, n + 1):
        for v in dag[u]:
            in_degree[v] += 1

    # Find nodes with in-degree 0
    queue = [u for u in range(1, n + 1) if in_degree[u] == 0]

    # For a unique topological sort, there should be exactly one node
    # with in-degree 0 at each step
    if len(queue) != 1:
        return False

    # Perform topological sort
    top_order = []
    while queue:
        u = queue.pop(0)
        top_order.append(u)

        for v in dag[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Check if we visited all nodes
    return len(top_order) == n

