import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    results = []

    for _ in range(t):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        # For each number, track its positions
        pos = {}
        for i, num in enumerate(a):
            if num not in pos:
                pos[num] = []
            pos[num].append(i)

        # For each number, calculate max gap
        max_gap = {}
        for num in pos:
            positions = pos[num]
            gaps = []
            # Gap before first occurrence
            gaps.append(positions[0])
            # Gaps between consecutive occurrences
            for i in range(1, len(positions)):
                gaps.append(positions[i] - positions[i-1])
            # Gap after last occurrence
            gaps.append(n - 1 - positions[-1])

            max_gap[num] = max(gaps)

        # For each k, find the minimum number with max_gap <= k-1
        res = []
        for k in range(1, n + 1):
            candidates = [num for num in max_gap if max_gap[num] <= k - 1]
            if candidates:
                res.append(str(min(candidates)))
            else:
                res.append("-1")

        results.append(" ".join(res) + " ")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
