import sys

def is_lucky(num):
    """Check if a number is lucky (only digits 4 and 7)."""
    s = str(num)
    return all(c in '47' for c in s)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    edges = []
    idx = 1
    for _ in range(n - 1):
        u = int(data[idx]); v = int(data[idx+1]); w = int(data[idx+2])
        idx += 3
        edges.append((u-1, v-1, w))

    # Build tree and find lucky edges
    tree = [[] for _ in range(n)]
    lucky_edges = set()
    for u, v, w in edges:
        tree[u].append((v, w))
        tree[v].append((u, w))
        if is_lucky(w):
            lucky_edges.add((min(u, v), max(u, v)))

    # For each vertex, find reachable set with at least one lucky edge
    total = 0
    for i in range(n):
        # Use BFS to find all reachable vertices from i with at least one lucky edge
        from collections import deque
        visited = set()
        queue = deque([(i, False)])  # (vertex, has_lucky)

        while queue:
            v, has_lucky = queue.popleft()
            if v == i:
                continue

            if has_lucky:
                visited.add(v)

            if not has_lucky:
                for neighbor, weight in tree[v]:
                    if is_lucky(weight):
                        queue.append((neighbor, True))

        lucky_count = len(visited)
        total += lucky_count * (lucky_count - 1)

    print(total)

if __name__ == "__main__":
    solve()
