import sys

def construct_permutation(n):
    """Construct a permutation of [1, 2, ..., n] that minimizes the sum of LIS and LDS lengths."""
    # We'll use groups of size k where k is about n/3
    k = n // 3
    if k == 0:
        k = 1

    permutation = []
    for i in range(1, n + 1):
        # Find the starting value for this group
        # Group i starts at n - i * k + 1
        start = n - i * k + 1

        # Add the elements of this group
        for j in range(start, start + k):
            if j > n:
                break
            permutation.append(j)

    return permutation

def main():
    n = int(sys.stdin.readline())
    permutation = construct_permutation(n)
    print(' '.join(map(str, permutation)))

if __name__ == "__main__":
