def is_lucky(w):
    """Check if a number is lucky (only contains digits 4 and 7)."""
    return all(c in '47' for c in str(w))

def brute_force(n, edges):
    """Brute force to count valid triples (i, j, k) with distinct i, j, k, and paths i-j, i-k have at least one lucky edge."""
    tree = [[] for _ in range(n + 1)]
    for u, v, w in edges:
        tree[u].append((v, w))
        tree[v].append((u, w))

    def find_path(u, v):
        """Find path from u to v using DFS."""
        visited = set()
        parent = {}

        def dfs(node, prev):
            nonlocal visited, parent
            visited.add(node)
            parent[node] = prev
            for neighbor, weight in tree[node]:
                if neighbor != prev:
                    dfs(neighbor, node)

        dfs(u, -1)

        path = []
        while v != -1:
            path.append(v)
            v = parent[v]
        path.reverse()
        return path

    answer = 0
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if j == i:
                continue
            path_ij = find_path(i, j)
            has_lucky_ij = any(is_lucky(w) for _, w in tree[edge] for edge in zip(path_ij[:-1], path_ij[1:]))
            if not has_lucky_ij:
                continue
            for k in range(1, n + 1):
                if k == i or k == j:
                    continue
                path_ik = find_path(i, k)
                has_lucky_ik = any(is_lucky(w) for _, w in tree[edge] for edge in zip(path_ik[:-1], path_ik[1:]))
                if has_lucky_ik:
                    answer += 1
    return answer

# Test with example 1
edges1 = [(1, 2, 4), (1, 3, 2), (1, 4, 7)]
print(brute_force(4, edges1))  # Expected: 16

# Test with example 2
edges2 = [(1, 2, 4), (1, 3, 47), (1, 4, 7447)]
print(brute_force(4, edges2))  # Expected: 24
