import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = int(data[1])
    b = int(data[2])
    c = int(data[3])
    d = int(data[4])

    # Build tree
    parent = [0] * (n + 1)
    children = [[] for _ in range(n + 1)]
    idx = 5
    for i in range(2, n + 1):
        parent[i] = int(data[idx])
        children[parent[i]].append(i)
        idx += 1

    # Find offices (leaves)
    offices = []
    for i in range(2, n + 1):
        if len(children[i]) == 0:
            offices.append(i)

    # Function to find LCA
    def find_lca(u, v):
        # Move both to the same depth
        depth_u = 0
        while u != 1:
            u = parent[u]
            depth_u += 1

        depth_v = 0
        while v != 1:
            v = parent[v]
            depth_v += 1

        # Bring deeper node up
        if depth_u > depth_v:
            for _ in range(depth_u - depth_v):
                u = parent[u]
        else:
            for _ in range(depth_v - depth_u):
                v = parent[v]

        # Move both up until they meet
        while u != v:
            u = parent[u]
            v = parent[v]
        return u

    # Count offices in subtree
    def count_offices_in_subtree(root):
        count = 0
        stack = [root]
        while stack:
            node = stack.pop()
            if node in offices:
                count += 1
            for child in children[node]:
                stack.append(child)
        return count

    lca_ab = find_lca(a, b)
    lca_cd = find_lca(c, d)

    offices_ab = count_offices_in_subtree(lca_ab)
    offices_cd = count_offices_in_subtree(lca_cd)

    if offices_ab % 2 == 0 and offices_cd % 2 == 0:
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    solve()
