    dp = [0] * (n + 1)

    for i in range(n):
        # Option 1: don't place t here
        dp[i + 1] = dp[i]

        # Option 2: place t here if possible
        if i + m <= n and can_place(s, t, i):
            dp[i + m] = max(dp[i + m], dp[i] + 1)

