    for num in a:
        if num % m == 0:
            print("YES")
            return

    # If we have more than m elements, by pigeonhole principle there exists a subsequence
    if n > m:
        print("YES")
        return

    # For n <= m, use dynamic programming to track all possible remainders
    # dp[i] = True if we can get remainder i with some non-empty subsequence
    dp = [False] * m

    for num in a:
        mod = num % m

        # Create a new temporary set for the new remainders
        new_dp = dp.copy()

        # Add the current element as a new subsequence
        if not new_dp[mod]:
            new_dp[mod] = True

        # Combine with existing subsequences
        for i in range(m):
            if dp[i]:
                new_mod = (i + mod) % m
                if not new_dp[new_mod]:
                    new_dp[new_mod] = True

        dp = new_dp

    # Check if we found any remainder that is 0
    if dp[0]:
        print("YES")
    else:
        print("NO")

