        matrix = []
        for _ in range(n):
            row = list(map(int, input().split()))
            matrix.append(row)

        # Group positions that must have the same value
        groups = {}
        for i in range(n):
            for j in range(m):
                # Find the representative of the group
                # The representative is the position with the smallest row and column index
                rep_i = min(i, n - i - 1)
                rep_j = min(j, m - j - 1)

                # Check if we've seen this representative before
                if (rep_i, rep_j) not in groups:
                    groups[(rep_i, rep_j)] = []

                # Add all positions in this group
                groups[(rep_i, rep_j)].append(matrix[i][j])

        # Calculate total operations
        total = 0
        for group in groups.values():
            # Find the median to minimize absolute differences
            group.sort()
            median = group[len(group) // 2]
            for val in group:
                total += abs(val - median)

        print(total)

