import sys

def solve(s):
    # Try both protocols
    for protocol in ["http", "ftp"]:
        if s.startswith(protocol):
            remaining = s[len(protocol):]

            # Try all possible splits for "ru"
            for ru_pos in range(len(remaining) - 1):
                # Check if we have "ru" at this position
                if remaining[ru_pos] == 'r' and remaining[ru_pos + 1] == 'u':
                    # Split into domain, "ru", and context
                    domain = remaining[:ru_pos]
                    context = remaining[ru_pos + 2:]

                    # Check if domain is non-empty
                    if domain:
                        # If context is non-empty, we need to check if the original address had context
                        # The original address would have had "://", then domain, then ".ru", then "/<context>"
                        # When we remove punctuation, we get protocol + domain + "ru" + context
                        # So if context is non-empty, the original address had context
                        if context:
                            return f"{protocol}://{domain}.ru/{context}"
                        else:
                            return f"{protocol}://{domain}.ru"

    # If no protocol found (shouldn't happen as per problem statement)
    return s

def main():
    s = sys.stdin.read().strip()
    print(solve(s))

if __name__ == "__main__":
    main()
"}

