def has_good_triple(s, l, r):
    """Check if interval [l, r] (1-indexed) contains a good triple"""
    n = len(s)
    # Check if there's a good triple in [l, r]
    # A good triple spans positions i, i+1, i+2
    # So i must be in [l, r-2]
    for i in range(l - 1, min(r - 2, len(s) - 2) + 1):
        if s[i] == s[i+1] == s[i+2]:
            return True
    return False

